import sys
import re
import time
import six
from ute_tshark.exception import TsharkExecutionError
from ute_tshark.exception import ProcessIsAlreadyRunning
from ute_tshark.exception import StopProcessError, StartProcessError


class BaseTshark(object):

    """ Class to handle packets sniffer. """

    def __init__(self, ssh_client, tshark_dir, interface, log_dir, snaplen, preferences):

        """
        :param ssh_client:              SSHLibrary instance with established connection.
        :param string tshark_dir:       Path to dictionary where tshark is located.
        :param string interface:        Local or remote machine interface which is used to packects capture.
        :param string log_dir:          Directory path where pcap file is stored.
        :param integer snaplen:         Amount of data for each frame that is captured.


        """
        self._ssh = ssh_client
        self._tshark_dir = tshark_dir
        self._interface = interface
        self._log_dir = log_dir
        self._setup_log_dir(log_dir)
        self._snaplen = snaplen
        self._pid = None
        self._display_filter = self._get_display_filter()
        self._preferences = preferences

    @property
    def pid(self):
        """ Get process id.

        :return:        Shell process id.
        :rtype:         string
        """
        return self._pid

    @pid.setter
    def pid(self, pid):
        """ Set process id.

        :param string pid:      Shell process id.
        """
        if self._pid is not None:
            raise ProcessIsAlreadyRunning("%s process is running" % self.__class__.__name__)
        self._pid = pid

    def start_process(self, cmd, timecheck=10):
        """ Start process.

        :param string cmd:           Command to run.
        :param string timecheck:     Number of seconds to check if tshark execution exists (default: 10).
        """
        self.pid = self._execute(cmd)
        self._is_process_started(timecheck)

    def stop_process(self):
        """Stop process.

        """
        for i in range(0, 3):
            self._execute('kill -2 {} || true'.format(self.pid))
            if self._process_is_stopped(100):
                return
        raise StopProcessError("{} process was not be stopped. Tshark pid {} is still existing".format(self.__class__.__name__, self.pid))

    def _execute(self, cmd):
        out, err, rc = self._ssh.execute_command(cmd)
        out = out.strip()
        err = err.strip()
        if rc == 0:
            return out
        else:
            raise TsharkExecutionError(err)

    def _get_file(self, src, dst):
        return self._ssh.get_file(source=src, destination=dst)

    def _process_is_stopped(self, wait_time):
        start = time.time()
        try:
            while time.time() - start < wait_time:
                self._pid_exists()
                time.sleep(1)
        except TsharkExecutionError:
            self._pid = None
            if six.PY2:
                sys.exc_clear()
            return True
        else:
            return False

    def _process_is_not_stopped(self, wait_time):
        return not self._process_is_stopped(wait_time)

    def _is_process_started(self, timecheck):
        start = time.time()
        try:
            while time.time() - start < timecheck:
                self._pid_exists()
                time.sleep(1)
        except TsharkExecutionError:
            error = self._execute('cat {}/{}_tshark_error_log'.format(self._log_dir, self.__class__.__name__))
            self._pid = None
            raise StartProcessError("{} process was not started\n{}".format(self.__class__.__name__, error))

    def _pid_exists(self):
        self._execute("ps -ef | awk '{{print $2}}' | grep '^{}$'".format(self.pid))

    def _setup_log_dir(self, log_dir):
        try:
            self._execute('[ -d {} ]'.format(log_dir))
        except TsharkExecutionError:
            self._execute('mkdir -p {}'.format(log_dir))

    def _get_display_filter(self):
        try:
            self._execute('{}/tshark -h | grep "<display filter>"'.format(self._tshark_dir))
        except TsharkExecutionError:
            return '-R'
        else:
            return '-Y'
